1	import { describe, it, expect } from "vitest";
2	import { spawnSync } from "node:child_process";
3	import { runScenario } from "./claim-office.js";
4	
5	/**
6	 * Spawns the real CLI so the tests exercise the actual stdin/stdout/exit-status
7	 * contract rather than an internal function. Invokes the resolved tsx binary
8	 * directly — going through `npx` costs ~200 ms per call in package resolution.
9	 */
10	const runCli = (stdin: string) =>
11	  spawnSync("node_modules/.bin/tsx", ["src/cli.ts"], {
12	    input: stdin,
13	    encoding: "utf8",
14	  });
15	
16	describe("MHPCO Claim Office", () => {
17	  // --- Base premiums: single main items (each + 10% first insurance + 5 G fee) ---
18	  it("quotes an empty item list as 5 G (processing fee only)", () => {
19	    const scenario = {
20	      customer: { yearsWithMHPCO: 0 },
21	      steps: [{ op: "quote", items: [] }],
22	    };
23	
24	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
25	  });
26	  it("quotes a plain sword (base 100 G) as 115 G", () => {
27	    const scenario = {
28	      customer: { yearsWithMHPCO: 0 },
29	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
30	    };
31	
32	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
33	  });
34	  it("quotes a plain amulet (base 60 G) as 71 G", () => {
35	    const scenario = {
36	      customer: { yearsWithMHPCO: 0 },
37	      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
38	    };
39	
40	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
41	  });
42	  it("quotes a plain staff (base 80 G) as 93 G", () => {
43	    const scenario = {
44	      customer: { yearsWithMHPCO: 0 },
45	      steps: [{ op: "quote", items: [{ type: "staff" }] }],
46	    };
47	
48	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 93 }] });
49	  });
50	  it("quotes a plain potion (base 40 G) as 49 G", () => {
51	    const scenario = {
52	      customer: { yearsWithMHPCO: 0 },
53	      steps: [{ op: "quote", items: [{ type: "potion" }] }],
54	    };
55	
56	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 49 }] });
57	  });
58	
59	  // --- Components and the building block of 3 alike ---
60	  it("quotes 2 runes as base premium 50 G", () => {
61	    const scenario = {
62	      customer: { yearsWithMHPCO: 0 },
63	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
64	    };
65	
66	    // base 50 + 10 % first insurance (5) + 5 fee = 60
67	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
68	  });
69	  it("quotes 3 runes as base premium 60 G (block applies)", () => {
70	    const scenario = {
71	      customer: { yearsWithMHPCO: 0 },
72	      steps: [
73	        {
74	          op: "quote",
75	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
76	        },
77	      ],
78	    };
79	
80	    // base 60 (block) + 10 % first insurance (6) + 5 fee = 71
81	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
82	  });
83	  it("quotes 4 runes as base premium 100 G (no block — block requires exactly 3)", () => {
84	    const scenario = {
85	      customer: { yearsWithMHPCO: 0 },
86	      steps: [
87	        {
88	          op: "quote",
89	          items: [
90	            { type: "rune" },
91	            { type: "rune" },
92	            { type: "rune" },
93	            { type: "rune" },
94	          ],
95	        },
96	      ],
97	    };
98	
99	    // base 100 (no block) + 10 % first insurance (10) + 5 fee = 115
100	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
101	  });
102	  it("quotes 7 runes as base premium 175 G", () => {
103	    const scenario = {
104	      customer: { yearsWithMHPCO: 0 },
105	      steps: [
106	        {
107	          op: "quote",
108	          items: Array.from({ length: 7 }, () => ({ type: "rune" })),
109	        },
110	      ],
111	    };
112	
113	    // base 175 (7 x 25, no block) + 10 % first insurance (17.5) + 5 fee
114	    // = 197.5, rounded up in the MHPCO's favour = 198
115	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 198 }] });
116	  });
117	  it("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types)", () => {
118	    const scenario = {
119	      customer: { yearsWithMHPCO: 0 },
120	      steps: [
121	        {
122	          op: "quote",
